-- =====================================================================
-- Session 155 — Matt 22 extras-tier cross-references (single chapter)
-- =====================================================================
-- Adds Matt 22's extras-tier rows + threads to the cross-reference
-- corpus. Continues the S131 (Matt 1-2) -> S146 (Matt 16) -> S154
-- (Matt 17) extras-tier coverage; Matt 22 lands as the system''s-
-- questioning-day-in-the-Temple chapter — the closing of the public-
-- engagement the prior chapter''s authority-challenge had opened —
-- walking five framework-bearing narrative-movements that the King-of-
-- Yashar''el (Israel) walks-out-against the religious-leadership-system
-- progressively:
--
--   (a) the parable-of-the-marriage-feast (vv.1-14) — the Messianic-
--       banquet-substance the prophet Yeshayahu (Isaiah) had named
--       (Isaiah 25:6, 55:1-3, 61:10) the apostle Yochanan (John) will
--       name at Revelation 19:7-9 (*the marriage of the Lamb*); the
--       bidden-leadership-stewards refusing and slaying-the-servants
--       (the same Tanakh-prophet-killing-pattern Matt 21''s husbandmen-
--       parable had walked); the king''s-judgment burning-the-city as
--       real-judgment pre-figuring the 70 CE destruction of Yerushalayim
--       (Jerusalem) the King names explicitly at Matt 24:2 and 23:38;
--       the highways-and-hedges-gathering as the scattered-seed of the
--       twelve tribes coming-home per Hosea 1:9-10 + Isaiah 11:11-12 +
--       Ezekiel 37:21 + Zechariah 10:8-10 (NOT the church-replacing-
--       Yashar''el substance per Red Line #11); the *both bad and good*
--       gathered as the pre-sifting-substance the wheat-and-tares
--       (Matt 13:24-30) and the dragnet (Matt 13:47-50) had laid as the
--       kingdom-architecture; the wedding-garment-substance the prophet
--       Yeshayahu (Isaiah) at Isaiah 61:10''s garments-of-salvation and
--       the prophet Zecharyah (Zechariah) at Zechariah 3:3-5''s change-
--       of-raiment had named, the apostle Yochanan (John) at Revelation
--       19:8 and 3:5 and 22:14 names as the righteousness-of-saints
--       walked-out per the heart-Torah of Jeremiah 31:31-34 + Ezekiel
--       36:26-27 — NOT the imputed-righteousness-without-substance-
--       walked the Reformation-substance had collapsed-the-gospel-into;
--       the man-without-the-garment cast-into-outer-darkness as the
--       post-harvest-sifting-substance per Red Line #11''s wheat-blotted-
--       out-by-walking-without-fruit architecture; *many are called,
--       but few are chosen* as the cause-and-effect-of-hearing
--       (John 10:26-27) the framework reads — hearing reveals what was
--       written before the foundation of the world, never creates.
--   (b) the tribute-to-Caesar question (vv.15-22) — Pharisees-and-
--       Herodians united-against-the-King at a forced-binary-trap; the
--       Roman-denarius bearing Tiberius Caesar''s image with the
--       inscription *TI CAESAR DIVI AVG F AVGVSTVS* (son of the divine
--       Augustus) on the obverse and *Pontifex Maximus* (supreme high-
--       priest) on the reverse — the substance the second-commandment
--       (Exodus 20:4-5) categorically walks against, carried into the
--       Temple-court itself in the speakers'' own purse; *whose is this
--       image and superscription?* — the Greek *eikōn* the apostle
--       Sha''ul (Paul) uses of the Son at Colossians 1:15 + the citizen
--       at Romans 8:29, the same Septuagint-Greek the Genesis 1:26-27
--       creation-substance carries; the citizen-of-the-kingdom bears
--       the image-of-Elohim (God) the same way the coin bears Caesar''s
--       image; *render therefore unto Caesar the things which are
--       Caesar''s; and unto Elohim (God) the things that are Elohim''s
--       (God''s)* — NOT the post-Constantinian collapse of two-co-equal-
--       spheres; the natural-administration operates under the
--       principalities-and-powers-of-the-darkness (Ephesians 6:12) the
--       Father permits-for-an-age. Apostolic-restatement at Romans 13:
--       1-7 + 1 Peter 2:13-17 with the categorical-precedence the
--       apostle Kefa (Peter) and the eleven walked-out at Acts 5:29 —
--       Shadrakh (Shadrach) / Meishakh (Meshach) / Aved-Nego (Abed-
--       nego) at Daniel 3; Daniel-substance at Daniel 6; the prophet
--       Eliyahu (Elijah) at 1 Kings 18; the apostle Yochanan (John)''s
--       apocalyptic-vision at Revelation 13''s beast-and-mark substance
--       the citizen-of-the-kingdom cannot receive even into suffering.
--   (c) the Sadducees-on-resurrection question (vv.23-33) — the
--       priestly-aristocracy-substance (the *Tsadoqim* descended from
--       Tsadoq (Zadok)) whose-Torah-only-no-resurrection-no-angels-no-
--       spirit substance Luke names at Acts 23:8; the King''s rebuke
--       *ye do err, not knowing the scriptures, nor the power of
--       Elohim (God)*; *as the angels of Elohim (God) in heaven* — the
--       non-fallen-still-in-heaven-substance, NOT the categorically-
--       non-marrying-of-all-angels (the watcher-substance of Genesis 6:
--       1-4 the prophet Chanok (Enoch) at 1 Enoch 6-7 and the apostle
--       Yahudah (Jude) at Jude 6 name); the citation of Exodus 3:6 — *I
--       am the Elohim (God) of Avraham (Abraham), and the Elohim (God)
--       of Yitschaq (Isaac), and the Elohim (God) of Ya''aqov (Jacob);
--       Elohim (God) is not the Elohim (God) of the dead, but of the
--       living*; the resurrection-substance the Tanakh-substance
--       carries throughout (Daniel 12:2, Isaiah 26:19, Hosea 13:14,
--       Job 19:25-27, Ezekiel 37:1-14, Psalm 16:10-11, 17:15, 49:15,
--       73:24); the apostle Sha''ul (Paul) at 1 Thessalonians 4:13-17
--       and 1 Corinthians 15 and the apostle Yochanan (John) at
--       Revelation 20:4-6''s *first resurrection* — the asleep-awaiting-
--       the-resurrection substance the framework reads, NOT the
--       inherited-Christian immediate-disembodied-soul-going-to-heaven-
--       or-hell-at-death substance.
--   (d) the great-commandment question (vv.34-40) — the Pharisaic-
--       lawyer-substance (*nomikos*) tempting the King with the
--       rabbinic-ranking-game over the 613 mitzvot; the King''s Shema-
--       citation (Deuteronomy 6:4-9) plus the Leviticus 19:18 neighbor-
--       substance plus the *all the law and the prophets hang* (Greek
--       *krematai* — suspension-from-a-load-bearing-point) — NOT the
--       post-Reformation collapse-of-Torah-into-two but the Torah-and-
--       the-prophets as the detailed-walking-out of love-of-Father and
--       love-of-neighbor; the heart-Torah of Jeremiah 31:31-34 +
--       Ezekiel 36:26-27 + Deuteronomy 30:6 + Deuteronomy 11:1 + Micah
--       6:8 + Hosea 6:6; the apostolic-restatement at Romans 13:8-10
--       (*love is the fulfilling of the law*) + Galatians 5:14 + James
--       2:8 + 1 John 4:20-21 + 1 John 5:2-3 (*the love of Elohim (God),
--       that we keep his commandments: and his commandments are not
--       grievous*).
--   (e) the David''s-Lord question (vv.41-46) — the framework-major
--       moment for the nature-of-God substance the Synoptic-substance
--       reaches. The King''s-citation of Psalm 110:1 — *Yahuah (the
--       LORD) said unto my Lord, Sit thou on my right hand* — the
--       Hebrew Tanakh preserving the substance with precision: the
--       first *Lord* is *Yahuah* (the tetragrammaton, the Formless-
--       Father per the framework''s Formless-Source / Formed-
--       Expression-from-the-Source nature-of-God reading); the second
--       *Lord* is *Adoni* (David''s personal-Lord, the Son the Davidic-
--       lineage produces AND who is greater than David). Psalm 110 is
--       the most-quoted Tanakh-Psalm in the apostolic-substance — the
--       King-himself before the Sanhedrin at Matt 26:64; Kefa-Pentecost
--       at Acts 2:34-36; Stephen at Acts 7:55-56; the apostle Sha''ul
--       (Paul) at Romans 8:34, 1 Corinthians 15:25, Ephesians 1:20,
--       Colossians 3:1; Hebrews 1:3, 1:13, 5:6, 7:17, 7:21, 8:1,
--       10:12-13, 12:2; the apostle Kefa (Peter) at 1 Peter 3:22; the
--       apostle Yochanan (John) at Revelation 3:21. The substance the
--       King walks at Psalm 110 rules out three inherited readings of
--       the nature-of-God: (i) the Trinitarian three-co-equal-persons-
--       of-one-substance the post-Nicene-post-Constantinian-substance
--       formulated — Psalm 110 has the Father telling the Son to sit
--       on his right hand and making the enemies the Son''s footstool,
--       substantive-subordination at the eternal-Source-and-Expression
--       level; (ii) the modalist-collapse of Father-and-Son into one-
--       undifferentiated-substance — the Father speaks TO the Son, the
--       two are substantively-distinct; (iii) the Arian-substance of
--       the Son as a created-being made-at-a-point-in-time — the Son
--       David calls *my Lord* is of the substantive-divine substance,
--       the Word the apostle Yochanan (John) names at John 1:1-3. The
--       system-substance has no answer; *and no man was able to answer
--       him a word, neither durst any man from that day forth ask him
--       any more questions* — the public-questioning is closed, the
--       road to the cross opens, the husbandmen-parable-substance of
--       Matt 21:38 (*come, let us kill him, and let us seize on his
--       inheritance*) walks out within the week.
--
-- Matt 22 reading-target: the chapter walks the heaviest framework-
-- bearing anchors in the Tanakh-substance directly (Isaiah 25:6 +
-- 55:1-3 + 61:10 wedding-feast-and-garments; Hosea 1:9-10 + Isaiah
-- 11:11-12 + Ezekiel 37:21 + Zechariah 10:8-10 scattered-seed-coming-
-- home; Exodus 20:4-5 image-and-superscription against Caesar''s-
-- divinity-claim; Genesis 1:26-27 image-of-Elohim stamping the citizen;
-- Ezekiel 44:15-16 + 2 Samuel 8:17 + 1 Kings 1:8 Tsadoqim-priestly-
-- aristocracy; Deuteronomy 25:5-10 levirate-marriage; Exodus 3:6 the
-- Father''s-self-disclosure naming the patriarchs as the living;
-- Daniel 12:2 + Isaiah 26:19 + Hosea 13:14 + Job 19:25-27 + Ezekiel
-- 37:1-14 + Psalm 16:10-11 the Tanakh-resurrection-substance; Genesis
-- 6:1-4 the watcher-rebellion the *as the angels in heaven* excludes;
-- Deuteronomy 6:4-9 the Shema; Leviticus 19:18 + 19:34 love-of-
-- neighbor-and-the-stranger-who-joins; Jeremiah 31:31-34 + Ezekiel
-- 36:26-27 the heart-Torah of the new covenant; 2 Samuel 7:12-16 +
-- Isaiah 9:6-7 + Isaiah 11:1 + Jeremiah 23:5-6 + Ezekiel 34:23-24 +
-- Ezekiel 37:24-25 the Davidic-covenant; Psalm 110:1 the framework-
-- major Formless-Father / Formed-Son architecture). The extras-library
-- adds five framework-bearing thread-clusters:
--   Thread 1: 2 Esdras 2:38-43 + 8:52 + Wisdom of Solomon 5:15-16''s
--     direct articulation of the kingdom-feast-on-Sion, the glorious-
--     garments-from-Yahuah, the young-man-taller-than-all-the-rest
--     setting crowns on the gathered, paradise-opened and time-to-come-
--     prepared, and the righteous receiving a glorious kingdom and
--     crown — the wisdom-stream''s direct corroboration of the wedding-
--     feast architecture at vv.1-14.
--   Thread 2: Sirach (Ecclesiasticus) 17:1-12 + Wisdom of Solomon
--     2:23 + 9:1''s articulation of the image-of-Elohim stamped on man
--     at creation and the law-of-life as everlasting-covenant — the
--     wisdom-stream''s direct corroboration of the *whose image and
--     superscription?* architecture at vv.15-22 (man bears the image
--     of Elohim per Bereshit (Genesis) 1:26-27 the same way the coin
--     bears Caesar''s image; what is stamped with the Father''s-image
--     belongs to the Father).
--   Thread 3: 2 Maccabees 7''s mother-and-seven-sons resurrection-
--     witness (vv.9, 23) + 2 Esdras 7:32 + Wisdom of Solomon 3:1''s
--     direct articulation of the resurrection-of-the-righteous and the
--     King-of-the-world-shall-raise-us-up substance — the wisdom-and-
--     martyrdom-stream''s strongest external anchor for the resurrection-
--     doctrine the King defends at vv.23-33 against the Sadducean-
--     denial.
--   Thread 4: Sirach (Ecclesiasticus) 7:30 + 17:14 + 28:2 + 28:7 +
--     Wisdom of Solomon 6:18''s direct articulation of the Shema-
--     architecture (love Yahuah with all your strength) + the
--     commandment-concerning-the-neighbor + the forgive-your-neighbor-
--     remember-the-covenant substance + love-is-the-keeping-of-her-
--     laws — the wisdom-stream''s direct corroboration of the King''s
--     two-commandments-and-the-Torah-and-the-prophets-hang answer at
--     vv.34-40.
--   Thread 5 (FRAMEWORK-MAJOR): 1 Enoch 46:3 + 48:2 + 51:3 + 61:8 +
--     62:7''s Son-of-Adam / Elect-One named-before-the-Head-of-Days +
--     seated-on-the-throne-of-glory architecture — the wisdom-stream''s
--     direct corroboration of the David''s-Lord substance at vv.41-46.
--     1 Enoch''s Parables-of-Enoch architecture (chs 37-71) names the
--     Son-of-Adam at the right-hand of the Head-of-Days centuries
--     before the King brings Psalm 110 into-the-system''s-face in the
--     Temple-court; the wisdom-stream and the gospel cohere at the
--     highest-substantial-substance-level the framework''s Formless-
--     Father / Formed-Son nature-of-God reading carries. FRAMEWORK-
--     MAJOR.
--
-- Jubilees, Jasher, Adam-Eve Conflict, Apocalypse of Abraham, and
-- Sonnini''s Acts of Paul do not surface framework-bearing Matt 22
-- connections at S155 (the chapter''s anchors are in the Tanakh-
-- prophets, the wisdom-stream of Sirach and Wisdom of Solomon, 1
-- Enoch''s Parables, 2 Maccabees 7''s resurrection-witness, and 2
-- Esdras''s apocalyptic-feast-and-resurrection material). The pseudepi-
-- grapha-Testaments-XII edition''s love-of-neighbor material at
-- Issachar / Gad / Joseph carries the substance Sirach 28 already
-- carries at the parsed-DB-level; the apocrypha-tier citations land
-- the substance more cleanly. 2 Baruch 30''s resurrection-passage is
-- absent from the current pseudepigrapha-charles-vol2 parse (the
-- parsed chapters are an extract-set; the standard ch 30 verses are
-- not in the DB). Historical-witness editions (Josephus, M.R. James''s
-- apocryphal NT, Lightfoot''s Apostolic Fathers) remain deferred from
-- V1 cross-refs per the historical-witness one-way rule. The lookup
-- view retains the S154 edition set for forward compatibility.
--
-- Five PROPOSED threads at extras-tier:
--   1. `the-wedding-feast-and-the-garments-of-the-righteous-in-2-esdras-and-wisdom-of-solomon`        (sort 332)
--   2. `render-unto-caesar-and-the-image-of-elohim-stamped-on-man-in-sirach-and-wisdom-of-solomon`    (sort 333)
--   3. `the-resurrection-of-the-righteous-witnessed-by-the-mother-and-seven-sons-and-the-wisdom-stream` (sort 334)
--   4. `love-of-yahuah-and-love-of-neighbor-as-the-shema-walked-out-in-sirach-and-wisdom-of-solomon`  (sort 335)
--   5. `the-elect-one-at-the-right-hand-the-davidic-lord-witnessed-in-1-enoch-parables`               (sort 336)
--
-- 22 new cross_references rows at tier_required=''extras'' (Library
-- tier, $4.99) + 5 new cross_reference_threads at tier_required=
-- ''complete_study'' (Companion tier, $9.99). The tier split honors the
-- chapter-end-card architecture established at S146 and prior: Layer 1
-- (per-verse cross-refs) visible to Library readers; Layer 2 (framework
-- thread callouts with summary_md + member_notes) gated at Companion.
-- Every member-note passes the 12 Red Lines and the 12-point editorial
-- checklist. The seed-mechanism per framework-deep''s *Paternal Seed
-- and the Marriage-Covenant Absorption* section + Red Line #7
-- augmentation does not surface in Matt 22 (no foreign-origin
-- individuals or seed-distinction substance in the chapter — the
-- chapter is internal to the Temple-court-confrontation between the
-- King and the religious-leadership-system of Yahudah (Judah)); the
-- highways-and-hedges-gathering at vv.8-10 is the scattered-seed-of-
-- the-twelve-tribes-coming-home per Red Line #11, NOT the categorically-
-- unrelated-nations-grafted-into-the-tree-by-faith-confession
-- substance. Hebrew names with internal apostrophes (Yashar''el,
-- Ya''aqov, Yechezk''el, Yo''el, Sha''ul, Tseva''ot, King''s, Father''s,
-- Yahuah''s, etc.) and English possessives (wisdom-stream''s, King''s,
-- system''s, etc.) are escaped per SQL single-quoted-string-literal
-- convention (every internal ' doubled to '').
--
-- Idempotent: ON CONFLICT DO NOTHING on every INSERT.
-- =====================================================================

\echo 'Session 155 — Matt 22 extras-tier cross-references migration starting...'
BEGIN;

-- Verse-lookup temp view. Mirrors the S154 view; retained for forward
-- compatibility even though Matt 22 surfaces only canon + enoch +
-- apocrypha at S155.
CREATE TEMP VIEW _s155_xref_lookup AS
SELECT
    e.slug AS edition_slug,
    b.slug AS book_slug,
    c.chapter_number,
    v.verse_number,
    v.id AS verse_id
  FROM verses v
  JOIN chapters c ON v.chapter_id = c.id
  JOIN books    b ON c.book_id    = b.id
  JOIN editions e ON b.edition_id = e.id
 WHERE e.slug IN (
       'canon',
       'enoch',
       'jubilees',
       'jasher',
       'apocrypha',
       'apocrypha-charles-vol1',
       'pseudepigrapha',
       'adam-eve-conflict',
       'apocalypse-of-abraham',
       'ascension-isaiah',
       'sonnini-acts-29'
   );

-- ---------------------------------------------------------------------
-- Insert 22 extras-tier cross_references rows.
-- ---------------------------------------------------------------------
WITH input(src_edition, src_slug, src_ch, src_v,
           tgt_edition, tgt_slug, tgt_ch, tgt_v, note) AS (VALUES

  -- Thread 1: the-wedding-feast-and-the-garments-of-the-righteous-in-2-esdras-and-wisdom-of-solomon
  ('canon', 'matthew', 22, 9, 'apocrypha', '2-esdras', 2, 38,
   '*Arise up and stand, behold the number of those that be sealed in the feast of Yahuah (God).* 2 Esdras 2:38 names the direct wisdom-stream verbal-anchor for the gathered-to-the-feast substance — the *number of those that be sealed in the feast of Yahuah (God)*. The framework reads the verse against Matt 22:9''s *go ye therefore into the highways, and as many as ye shall find, bid to the marriage.* The highways-and-hedges-gathering the king-substance sends-the-servants-into is the wisdom-stream''s sealed-in-the-feast-of-Yahuah substance — the gathering of the scattered-seed of the twelve-tribes per Red Line #11''s ingathering architecture the prophet Hoshea (Hosea) at Hosea 1:9-10, the prophet Yeshayahu (Isaiah) at Isaiah 11:11-12, the prophet Yechezk''el (Ezekiel) at Ezekiel 37:21, and the prophet Zecharyah (Zechariah) at Zechariah 10:8-10 had named. The substance is NOT the categorically-unrelated-nations-grafted-into-the-tree-by-faith-confession substance the inherited-Christian-replacement-theology had collapsed-the-substance-into; the substance is the wisdom-stream''s direct articulation of the sealed-citizens-of-the-kingdom gathered-to-the-Father''s-feast.'),

  ('canon', 'matthew', 22, 10, 'apocrypha', '2-esdras', 2, 42,
   '*I Esdras saw upon the mount Sion a great people, whom I could not number, and they all praised Yahuah (God) with songs.* 2 Esdras 2:42 names the wisdom-stream''s vision of the great-people-upon-the-mount-Tsion (Sion) substance — the gathered-multitude at the Father''s-feast. The framework reads the verse against Matt 22:10''s *and the wedding was furnished with guests.* The wedding-feast filled-with-guests at the king''s-table is the wisdom-stream''s great-people-upon-the-mount-Tsion-substance — the gathered-citizens of the kingdom the framework reads through the apostle Yochanan (John) at Revelation 7:9-17''s *a great multitude, which no man could number, of all nations, and kindreds, and people, and tongues* (the gathered-from-the-scattering substance per Red Line #11, NOT the gathered-from-categorically-unrelated-peoples substance). The wisdom-stream and the apostolic-vision cohere at the gathered-multitude-on-Sion architecture the King''s wedding-feast-parable walks-out.'),

  ('canon', 'matthew', 22, 11, 'apocrypha', '2-esdras', 2, 43,
   '*And in the midst of them there was a young man of a high stature, taller than all the rest, and upon every one of their heads he set crowns, and was more exalted.* 2 Esdras 2:43 names the wisdom-stream''s direct vision of the young-man-of-high-stature setting-crowns-upon-the-gathered substance — the Messianic-figure crowning the citizens at the Father''s-feast. The framework reads the verse against Matt 22:11''s *when the king came in to see the guests, he saw there a man which had not on a wedding garment.* The king-substance walking-among-the-guests at the wedding-feast is the wisdom-stream''s young-man-of-high-stature among-the-gathered. 2 Esdras 2:43 articulates the substance the gospel-wedding-feast walks at the historical-pivot — the Messianic-king walks-among the gathered-citizens and the substance-walked-with reveals the substance-walked-without (the man-without-the-garment receives no crown; the citizens-walking-in-the-righteousness-of-saints per Revelation 19:8 receive crowns).'),

  ('canon', 'matthew', 22, 12, 'apocrypha', 'the-wisdom-of-solomon', 5, 16,
   '*Therefore shall they receive a glorious kingdom, and a beautiful crown from the hand of Yahuah (God): for with his right hand shall he cover them, and with his arm shall he protect them.* Wisdom of Solomon 5:16 names the wisdom-stream''s direct articulation of the glorious-kingdom-and-beautiful-crown the righteous-citizen receives from-the-hand-of-Yahuah. The framework reads the verse against Matt 22:12''s *friend, how camest thou in hither not having a wedding garment? And he was speechless.* The wedding-garment-substance the king-substance categorically-requires is the substance the citizen-walking-in-the-righteousness-of-saints (Revelation 19:8) walks-in; the beautiful-crown of Wisdom of Solomon 5:16 is the substance received-from-the-Father''s-hand for the substance walked-out. The man-without-the-garment has-no-crown to receive because the substance-walked-into-the-feast was not the substance-the-feast-was-meant-to-be-walked-in; the speechless-substance at the king''s-question pre-figures the system''s-substance-silenced at v.46 (*no man was able to answer him a word*). The wisdom-stream had named the garment-and-crown architecture centuries before the wedding-feast-parable walks-it-out at the historical-pivot.'),

  -- Thread 2: render-unto-caesar-and-the-image-of-elohim-stamped-on-man-in-sirach-and-wisdom-of-solomon
  ('canon', 'matthew', 22, 20, 'apocrypha', 'ecclesiasticus', 17, 3,
   '*He endued them with strength by themselves, and made them according to his image.* Sirach (Ecclesiasticus) 17:3 names the direct wisdom-stream verbal-anchor for the image-of-Elohim-stamped-on-man substance — Sirach 17 carries the Bereshit (Genesis) 1:26-27 creation-substance forward at the wisdom-stream-register, articulating the substance-of-the-citizen-of-the-covenant bearing-the-Father''s-image the same way the coin bears Caesar''s. The framework reads the verse against Matt 22:20''s *whose is this image and superscription?* The Greek *eikōn* the King uses is the same Septuagint-Greek the Genesis 1:26-27 creation-substance carries and the apostle Sha''ul (Paul) uses of the Son-substance at Colossians 1:15 (*the image of the invisible Elohim (God)*) and of the citizen at Romans 8:29 (*conformed to the image of his Son*). The image-architecture the King invokes at the tribute-coin is the substance Sirach 17:3 had named the wisdom-stream-substance for; what is stamped with the Father''s-image belongs to the Father.'),

  ('canon', 'matthew', 22, 21, 'apocrypha', 'ecclesiasticus', 17, 11,
   '*Beside this he gave them knowledge, and the law of life for an heritage.* Sirach (Ecclesiasticus) 17:11 names the wisdom-stream''s direct articulation of the law-of-life-for-an-heritage substance — the Torah given to the citizen-stamped-with-the-Father''s-image as the inheritance, the substance Sirach 17:12 continues at *he made an everlasting covenant with them, and shewed them his judgments* and Sirach 24:23 names as *all these things are the book of the covenant of the most high Yahuah (God), even the law which Moses commanded for an heritage to the congregations of Ya''aqov (Jacob).* The framework reads the verse against Matt 22:21''s *render therefore unto Caesar the things which are Caesar''s; and unto Elohim (God) the things that are Elohim''s (God''s).* The substance the citizen renders-back-to-the-Father is the substance the Father stamped-the-citizen-with — the image, and the law-of-life-for-an-heritage Sirach 17:11 names the wisdom-stream-substance for. Per Red Line #4: Torah is NOT the curse but the covenant-inheritance the Father stamped on the citizen; per the framework''s reading of grace-as-return-to-the-way, the citizen-rendering-back-to-the-Father walks the heart-Torah of Jeremiah 31:31-34 and Ezekiel 36:26-27 from the inside.'),

  ('canon', 'matthew', 22, 20, 'apocrypha', 'the-wisdom-of-solomon', 2, 23,
   '*For Yahuah (God) created man to be immortal, and made him to be an image of his own eternity.* Wisdom of Solomon 2:23 names the wisdom-stream''s direct verbal-anchor for the image-of-Elohim-as-image-of-his-own-eternity substance. The framework reads the verse against Matt 22:20''s *whose is this image and superscription?* The image-architecture the King invokes at the tribute-coin operates at two-registers-at-once: the Caesar-coin bears Caesar''s perishable-image; the citizen-of-the-kingdom bears the image-of-Elohim''s-own-eternity. The Caesar-coin returns to Caesar; the citizen-stamped-with-the-image-of-his-own-eternity returns to the Father who-stamped-him with the substance Wisdom of Solomon 2:23 names the wisdom-stream-substance for. The framework reads this in continuity with John 1:18''s *no man hath seen Elohim (God) at any time; the only begotten Son, which is in the bosom of the Father, he hath declared him* — the citizen-stamped-with-the-image is being-conformed-to-the-image-of-the-Son the apostle Sha''ul (Paul) names at Romans 8:29, the substance walked-out from the Formless-Source through the Formed-Expression into the citizen-of-the-kingdom.'),

  ('canon', 'matthew', 22, 21, 'apocrypha', 'the-wisdom-of-solomon', 9, 1,
   '*O Yahuah (God) of my fathers, and Yahuah (God) of mercy, who have made all things with your word.* Wisdom of Solomon 9:1 names the wisdom-stream''s direct articulation of the made-all-things-with-thy-word substance — the same substance the apostle Yochanan (John) walks at John 1:1-3 (*in the beginning was the Word, and the Word was with Elohim (God), and the Word was Elohim (God) ... all things were made by him*). The framework reads the verse against Matt 22:21''s *unto Elohim (God) the things that are Elohim''s (God''s).* The substance-the-Father-claims is the substance-the-Father-made-with-his-Word; the Word-through-whom-all-things-were-made is the Formed-Expression the framework''s nature-of-God reading names (the Son who-spoke-at-creation, who-spoke-at-Sinai, who-spoke-from-the-bright-cloud at the transfiguration, who-walks-the-tribute-question at the Temple-court). The substance Caesar-stamped belongs to Caesar; the substance the Father-and-the-Son-made-together belongs to the Father — and the Father-and-the-Son are substantially-one in the Source-and-Expression substance the next thread''s Psalm 110-architecture walks-out at the framework-major level.'),

  -- Thread 3: the-resurrection-of-the-righteous-witnessed-by-the-mother-and-seven-sons-and-the-wisdom-stream
  ('canon', 'matthew', 22, 29, 'apocrypha', '2-maccabees', 7, 9,
   '*And when he was at the last gasp, he said, You like a fury takest us out of this present life, but the King of the world shall raise us up, who have died for his laws, to everlasting life.* 2 Maccabees 7:9 names THE direct wisdom-and-martyrdom-stream verbal-anchor for the resurrection-of-the-righteous substance — the second son of the mother-and-seven-sons-substance under Antiochus Epiphanes confessing-the-King-of-the-world-shall-raise-us-up before-dying-for-his-laws. The framework reads the verse against Matt 22:29''s *ye do err, not knowing the scriptures, nor the power of Elohim (God).* The Sadducean-substance categorically-denies the resurrection (Acts 23:8); the wisdom-and-martyrdom-substance of 2 Maccabees 7 articulates the resurrection-doctrine at the strongest external-witness-register the Second-Temple-period produced — seven sons and their mother dying-for-the-Torah confessing-the-King-of-the-world-shall-raise-us-up to-everlasting-life. The substance the King defends at vv.23-33 is the substance the wisdom-and-martyrdom-stream had already-confessed at the cost-of-blood centuries before the Sadducean-trap-question.'),

  ('canon', 'matthew', 22, 32, 'apocrypha', '2-maccabees', 7, 23,
   '*But doubtless the Creator of the world, who formed the generation of man, and found out the beginning of all things, will also of his own mercy give you breath and life again, as you now regard not your own selves for his laws'' sake.* 2 Maccabees 7:23 names the wisdom-and-martyrdom-stream''s direct articulation of the Creator-shall-give-breath-and-life-again substance — the mother of the seven sons confessing the resurrection-doctrine to her sons in their hearing as they die. The framework reads the verse against Matt 22:32''s *I am the Elohim (God) of Avraham (Abraham), and the Elohim (God) of Yitschaq (Isaac), and the Elohim (God) of Ya''aqov (Jacob); Elohim (God) is not the Elohim (God) of the dead, but of the living.* The King''s-citation of Exodus 3:6 walks the same substance the mother-of-the-seven-sons walks at 2 Maccabees 7:23 — the Creator who-formed-the-generation-of-man will-give-breath-and-life-again because the substance-of-the-Father-relating-to-the-patriarchs-and-the-citizens is the substance-of-the-living. The framework reads the asleep-awaiting-the-first-resurrection substance through this anchor — the patriarchs and the seven martyred-sons-and-their-mother are asleep, awaiting the Father''s-substance to give-breath-and-life-again, NOT the inherited-Christian immediate-disembodied-soul-going-to-heaven-or-hell-at-death substance the modern-Christian-pulpit had collapsed-the-grief-substance-of-the-citizen-into.'),

  ('canon', 'matthew', 22, 31, 'apocrypha', '2-esdras', 7, 32,
   '*And the earth shall restore those that are asleep in her, and so shall the dust those that dwell in silence, and the secret places shall deliver those souls that were committed unto them.* 2 Esdras 7:32 names THE direct wisdom-stream verbal-anchor for the earth-shall-restore-those-that-are-asleep substance — the resurrection-of-the-asleep substance the prophet Daniel had named at Daniel 12:2 (*many of them that sleep in the dust of the earth shall awake*) carried forward at the apocalyptic-wisdom-stream-register. The framework reads the verse against Matt 22:31''s *but as touching the resurrection of the dead, have ye not read that which was spoken unto you by Elohim (God).* The substance the King reads-to-the-Sadducean-substance is the substance 2 Esdras 7:32 had named the wisdom-stream-substance for — the earth-and-the-dust-and-the-secret-places restoring-the-asleep at the resurrection-day. The framework reads this in continuity with Red Line #11''s post-harvest-sifting architecture and the apostle Yochanan (John) at Revelation 20:4-6''s *first resurrection* — the asleep-awaiting-the-resurrection substance is the framework''s reading, NOT the immediate-disembodied-soul substance.'),

  ('canon', 'matthew', 22, 32, 'apocrypha', 'the-wisdom-of-solomon', 3, 1,
   '*But the souls of the righteous are in the hand of Yahuah (God), and there shall no torment touch them.* Wisdom of Solomon 3:1 names the wisdom-stream''s direct articulation of the souls-of-the-righteous-in-the-hand-of-Yahuah substance — read carefully through the framework, this is the asleep-in-the-Father''s-keeping substance, the substance-of-the-Father-holding-the-citizens-He-will-raise, NOT the inherited-Christian immediate-conscious-disembodied-soul-going-to-heaven substance the Wisdom of Solomon 3 surrounding-context (vv.7-8 — *and in the time of their visitation they shall shine ... they shall judge the nations*) makes plain belongs to the resurrection-day-substance not to the immediate-after-death-substance. The framework reads the verse against Matt 22:32''s *Elohim (God) is not the Elohim (God) of the dead, but of the living.* The Father-relating-to-the-asleep-as-the-living is the substance Wisdom of Solomon 3:1 names — the souls-of-the-righteous-are-in-the-hand-of-Yahuah because the Father holds-them-for-the-resurrection-day, the substance the citizen-of-the-kingdom can grieve-with-hope (*not as others which have no hope,* the apostle Sha''ul (Paul) at 1 Thessalonians 4:13) but should not grieve with the inherited-Christian collapsed-into-immediate-disembodied-substance.'),

  -- Thread 4: love-of-yahuah-and-love-of-neighbor-as-the-shema-walked-out-in-sirach-and-wisdom-of-solomon
  ('canon', 'matthew', 22, 37, 'apocrypha', 'ecclesiasticus', 7, 30,
   '*Love him that made you with all your strength, and forsake not his ministers.* Sirach (Ecclesiasticus) 7:30 names THE direct wisdom-stream verbal-anchor for the love-Yahuah-with-all-thy-strength substance — Sirach 7:30 carries the Shema-substance of Devarim (Deuteronomy) 6:5 forward at the wisdom-stream-register, articulating the love-him-that-made-you-with-all-your-strength substance. The framework reads the verse against Matt 22:37''s *thou shalt love Yahuah (the LORD) thy Elohim (God) with all thy heart, and with all thy soul, and with all thy mind.* The King''s-citation of the Shema is the substance the wisdom-stream had already-articulated at Sirach 7:30 — the love-Yahuah-with-all-thy-strength substance the Father called-the-citizen-to walk-out twice-daily in the substance-of-the-Shema-recitation. The substance is NOT the post-Reformation collapse-of-the-commandments-into-replacement-of-the-Torah; the substance is the heart-Torah of Jeremiah 31:31-34 + Ezekiel 36:26-27 walked-out from-the-inside through the Spirit-internalized-substance.'),

  ('canon', 'matthew', 22, 39, 'apocrypha', 'ecclesiasticus', 17, 14,
   '*And he said to them, Beware of all unrighteousness; and he gave every man commandment concerning his neighbour.* Sirach (Ecclesiasticus) 17:14 names THE direct wisdom-stream verbal-anchor for the commandment-concerning-the-neighbor substance — Sirach 17:14 carries the Vayikra (Leviticus) 19:18 love-thy-neighbor substance forward at the wisdom-stream-register, naming the architecture explicitly as the Father giving-every-man-commandment-concerning-his-neighbor. The framework reads the verse against Matt 22:39''s *and the second is like unto it, Thou shalt love thy neighbour as thyself.* The King''s-citation of Leviticus 19:18 is the substance the wisdom-stream had already-articulated at Sirach 17:14 — the every-man-commandment-concerning-his-neighbor substance the Father walked-into the substance-of-the-Torah from-the-beginning. The substance is NOT the modern-liberal categorically-universal-neighbor collapse the Lukan Good Samaritan parable is sometimes pressed-into; the substance is the substance-of-the-covenant-fellow-citizen plus-the-stranger-who-joins-the-covenant (Leviticus 19:34) plus-the-substance-of-mercy-walked-where-the-substance-of-need-is-encountered.'),

  ('canon', 'matthew', 22, 39, 'apocrypha', 'ecclesiasticus', 28, 2,
   '*Forgive your neighbour the hurt that he has done to you, so shall your sins also be forgiven when you prayest.* Sirach (Ecclesiasticus) 28:2 names the wisdom-stream''s direct articulation of the forgive-your-neighbor substance — the same substance the King will walk at Matthew 6:14-15''s *if ye forgive men their trespasses, your heavenly Father will also forgive you* and at the unforgiving-servant parable at Matthew 18:23-35. The framework reads the verse against Matt 22:39''s *thou shalt love thy neighbour as thyself.* The love-of-the-neighbor substance walks the substance-of-forgiveness; Sirach 28:2 had articulated the substance the King walks-out at the kingdom-citizen-substance — the forgive-as-you-have-been-forgiven architecture the wisdom-stream had named the prefiguring-substance for, the King brings into-effect at the kingdom-citizen-substance.'),

  ('canon', 'matthew', 22, 40, 'apocrypha', 'ecclesiasticus', 28, 7,
   '*Remember the commandments, and bear no malice to your neighbour: remember the covenant of the Highest, and wink at ignorance.* Sirach (Ecclesiasticus) 28:7 names the wisdom-stream''s direct articulation of the remember-the-commandments-and-the-covenant substance — the substance the King walks at Matt 22:40''s *on these two commandments hang all the law and the prophets.* The framework reads the verse as the wisdom-stream''s direct corroboration of the substance the King walks at the close of the great-commandment-answer: the two-commandments and the Torah-and-the-prophets are one-substance; the citizen-of-the-kingdom remembers-the-commandments and remembers-the-covenant-of-the-Highest and walks-the-substance-of-the-love-of-the-neighbor. NOT the post-Reformation collapse-of-the-Torah-into-the-two (the substance the wisdom-stream had categorically-walked-against by binding-the-commandments-and-the-covenant together in one substance); the substance is the heart-Torah of Jeremiah 31:31-34 + Ezekiel 36:26-27 walked-out from-the-inside.'),

  ('canon', 'matthew', 22, 40, 'apocrypha', 'the-wisdom-of-solomon', 6, 18,
   '*And love is the keeping of her laws; and the giving heed to her laws is the assurance of incorruption.* Wisdom of Solomon 6:18 names THE direct wisdom-stream verbal-anchor for the love-is-the-keeping-of-her-laws substance — the same substance the apostle Yochanan (John) will name explicitly at 1 John 5:2-3 (*this is the love of Elohim (God), that we keep his commandments: and his commandments are not grievous*). The framework reads the verse against Matt 22:40''s *on these two commandments hang all the law and the prophets.* The wisdom-stream had walked the substance-of-love-as-the-keeping-of-the-laws centuries before the King brings the Shema-and-the-neighbor-substance into-the-system''s-face in the Temple-court. The substance is the heart-Torah-architecture: love-of-Yahuah is the keeping-of-the-commandments; the keeping-of-the-commandments is the substance the new-heart-and-new-spirit of Ezekiel 36:26-27 walks-out from-the-inside; the *two commandments and the Torah and the prophets are one substance* per Red Line #4 + the framework''s grace-as-return-to-the-way reading.'),

  -- Thread 5: the-elect-one-at-the-right-hand-the-davidic-lord-witnessed-in-1-enoch-parables
  ('canon', 'matthew', 22, 42, 'enoch', '1-enoch', 46, 3,
   '*And he answered and said unto me: This is the Son of Adam who hath righteousness, with whom dwelleth righteousness, and who revealeth all the treasures of that which is hidden, because Yahuah (God) of Spirits hath chosen him, and whose lot hath the pre-eminence before Yahuah (God) of Spirits in uprightness for ever.* 1 Enoch 46:3 names THE direct wisdom-stream verbal-anchor for the Son-of-Adam-who-hath-righteousness substance — the Parables-of-Enoch identify the Son-of-Adam by name and articulate the architecture the King brings-into-the-Pharisaic-system''s-face at the David''s-Lord question. The framework reads the verse against Matt 22:42''s *what think ye of Messiah (Christ)? whose son is he? They say unto him, The son of David.* The Pharisaic-answer is correct as-far-as-it-goes — the Messiah is the son-of-David per the Davidic-covenant of 2 Samuel 7:12-16 + Isaiah 9:6-7 + Isaiah 11:1 + Jeremiah 23:5-6 + Ezekiel 34:23-24. But 1 Enoch 46:3 names the substance the Pharisaic-answer cannot-account-for — the Son-of-Adam pre-existing-the-Davidic-descent (*whose lot hath the pre-eminence before Yahuah (God) of Spirits in uprightness for ever*); the Son the King walks-into at the Psalm-110 citation is the Son-of-Adam the wisdom-stream had named the substance the Pharisaic-substance could-only-walk-the-Davidic-half-of. Per Red Line #12''s Son-of-Adam architecture, the 1 Enoch 46:3 naming-by-title-of-the-Son-of-Adam stands as the named-figure (NOT the kaph-comparative case of Daniel 7:13 / Revelation 1:13 / Revelation 14:14 the Red Line carves-out separately). FRAMEWORK-MAJOR.'),

  ('canon', 'matthew', 22, 43, 'enoch', '1-enoch', 48, 2,
   '*And at that hour that Son of Adam was named In the presence of Yahuah (God) of Spirits, And his name before the Head of Days.* 1 Enoch 48:2 names the wisdom-stream''s direct articulation of the Son-of-Adam-named-before-the-Head-of-Days substance — the pre-existence and the eternal-naming of the Son before the foundation of the world the apostle Yochanan (John) will name at Revelation 13:8 + 17:8 (the Book of Life of the Lamb slain-from-the-foundation-of-the-world). The framework reads the verse against Matt 22:43''s *how then doth David in spirit call him Lord, saying ...* The substance David walks at-Psalm-110 — David-the-prophet-in-the-Spirit calling-the-Messianic-substance *my Lord* — is the substance 1 Enoch 48:2 had named at the wisdom-stream-register: the Son-of-Adam was named before the Head of Days before the substance of the Davidic-line existed. The substance the Pharisaic-answer cannot-account-for at vv.42-46 is the substance 1 Enoch 48:2 had named at the heavenly-substance-register: the Son-of-Adam is greater-than-David because the Son-of-Adam was-named before-the-Head-of-Days before-the-Davidic-line-existed. FRAMEWORK-MAJOR.'),

  ('canon', 'matthew', 22, 44, 'enoch', '1-enoch', 51, 3,
   '*And the Elect One shall in those days sit on My throne, And his mouth shall pour forth all the secrets of wisdom and counsel: For Yahuah (God) of Spirits hath given them to him and hath glorified him.* 1 Enoch 51:3 names the wisdom-stream''s direct verbal-anchor for the Elect-One-shall-sit-on-My-throne substance — the same substance Psalm 110:1 walks at *Yahuah (the LORD) said unto my Lord, Sit thou on my right hand* — and the framework reads the 1 Enoch 51:3 substance as the wisdom-stream''s direct corroboration of the substance the King brings-into-the-Pharisaic-system''s-face at vv.44-45. The framework reads the verse against Matt 22:44''s citation of Psalm 110:1. The Father (the Head of Days / Yahuah of Spirits) gives-the-throne-to-the-Elect-One / Son-of-Adam; the substance is the substantive-subordination of the Son-to-the-Father per the framework''s Formless-Source / Formed-Expression nature-of-God reading (the substance categorically-rules-out the post-Nicene three-co-equal-persons-of-one-substance the post-Constantinian-substance formulated, the modalist-collapse, and the Arian-created-being substance). 1 Enoch 51:3 had named the substance the King''s Psalm-110-citation walks-out. FRAMEWORK-MAJOR.'),

  ('canon', 'matthew', 22, 44, 'enoch', '1-enoch', 61, 8,
   '*And the Head of Days placed the Elect One on the throne of His glory; And he shall judge all the works of the holy in heaven above, And weigh their deeds in the balance.* 1 Enoch 61:8 names the wisdom-stream''s direct articulation of the Head-of-Days-placing-the-Elect-One-on-the-throne-of-His-glory substance — the Father placing-the-Son at-the-Father''s-right-hand the same substance Psalm 110:1 walks. The framework reads the verse against Matt 22:44''s *sit thou on my right hand.* The substance the King-walks at Psalm-110 is the substance 1 Enoch 61:8 had named at the wisdom-stream-register — the Father (the Head of Days) places-the-Elect-One on-the-throne-of-His-glory. The substance is the framework-major Formless-Father / Formed-Son architecture: the Father is the Formless-Source the apostle Yochanan (John) names at John 1:18 (*no man hath seen Elohim (God) at any time*); the Son is the Formed-Expression-from-the-Source who-sits-at-the-Father''s-right-hand and walks-the-judgment-of-the-works-of-the-holy. The wisdom-stream and the Tanakh and the gospel cohere at the substance the King brings-into-the-Pharisaic-system''s-face. FRAMEWORK-MAJOR.'),

  ('canon', 'matthew', 22, 45, 'enoch', '1-enoch', 62, 7,
   '*And Yahuah (God) of Spirits said: This is the Son of Adam who is born unto righteousness, And righteousness abides over him, And the righteousness of the Head of Days forsakes him not.* 1 Enoch 62:7 names the wisdom-stream''s direct articulation of the Son-of-Adam-born-unto-righteousness substance — the Father naming-the-Son and the righteousness-of-the-Head-of-Days abiding-over-him. The framework reads the verse against Matt 22:45''s *if David then call him Lord, how is he his son?* The substance the Pharisaic-substance cannot-resolve is the substance 1 Enoch 62:7 had named the wisdom-stream-substance for — the Son-of-Adam is born-unto-righteousness (the Davidic-lineage substance the Pharisaic-answer walked) AND the righteousness-of-the-Head-of-Days abides-over-him from-the-foundation-of-the-world (the substance-greater-than-David the Pharisaic-substance cannot-account-for). The substance the King brings-into-the-Pharisaic-system''s-face at the close of the chapter is the same substance the wisdom-stream had named the architecture for. FRAMEWORK-MAJOR.')

)
INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, 'extras'::content_tier
  FROM input i
  JOIN _s155_xref_lookup sv ON sv.edition_slug   = i.src_edition
                           AND sv.book_slug      = i.src_slug
                           AND sv.chapter_number = i.src_ch
                           AND sv.verse_number   = i.src_v
  JOIN _s155_xref_lookup tv ON tv.edition_slug   = i.tgt_edition
                           AND tv.book_slug      = i.tgt_slug
                           AND tv.chapter_number = i.tgt_ch
                           AND tv.verse_number   = i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

