-- Thread 1 (sort 332): the-wedding-feast-and-the-garments-of-the-righteous-in-2-esdras-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-wedding-feast-and-the-garments-of-the-righteous-in-2-esdras-and-wisdom-of-solomon',
       'The wedding feast and the garments of the righteous — 2 Esdras 2 and Wisdom of Solomon 5''s wisdom-stream witness to Matt 22:1-14',
       'Matt 22:1-14''s parable-of-the-marriage-feast — the kingdom-banquet the King-substance walks-out against the leadership-stewards the prior chapter''s husbandmen-parable had named — read against the wisdom-stream''s direct articulation of the gathered-to-the-feast / great-people-upon-Mount-Tsion / young-man-of-high-stature-setting-crowns / glorious-kingdom-and-beautiful-crown substance. Four moves: 2 Esdras 2:38 names the wisdom-stream verbal-anchor for the gathered *in the feast of Yahuah (God)* substance the King''s servants-walking-into-the-highways-and-hedges at Matt 22:9 brings into-effect; 2 Esdras 2:42 names the great-people-upon-Mount-Tsion the wedding-feast-furnished-with-guests at Matt 22:10 walks-out; 2 Esdras 2:43 names the young-man-of-high-stature setting-crowns-upon-the-gathered the king-substance-walking-among-the-guests at Matt 22:11 walks-out at the historical-pivot; Wisdom of Solomon 5:16 names the glorious-kingdom-and-beautiful-crown the citizen-walking-in-the-wedding-garment receives at Matt 22:12-13 the man-without-the-garment cannot. The framework reads the cluster in continuity with Red Line #11''s ingathering-of-the-paternal-blood-remnant-of-the-twelve-tribes architecture (the highways-and-hedges-gathering is the scattered-seed coming-home per Hosea 1:9-10 + Isaiah 11:11-12 + Ezekiel 37:21 + Zechariah 10:8-10, NOT the categorically-unrelated-nations-grafted-by-faith-confession substance the inherited-Christian-replacement-theology had collapsed-the-substance-into) and in continuity with the post-harvest-sifting-architecture (the wedding-garment is the substance-walked-after-the-door-is-passed-through per Revelation 19:8 + 22:14, NOT the imputed-righteousness-without-substance-walked the Reformation-substance had collapsed-the-gospel-into; the man-without-the-garment cast-into-outer-darkness is the wheat-blotted-out-by-walking-without-fruit per Revelation 3:5 + Matthew 7:21-23, NOT a warning-to-tares the tares had-never-been-written). The wisdom-stream and the apostolic-vision cohere at the gathered-multitude-on-Sion architecture the King''s wedding-feast-parable walks-out.',
       sv.verse_id, ev.verse_id, 'complete_study', 332
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 22 AND sv.verse_number = 1
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 22 AND ev.verse_number = 14
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 333): render-unto-caesar-and-the-image-of-elohim-stamped-on-man-in-sirach-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'render-unto-caesar-and-the-image-of-elohim-stamped-on-man-in-sirach-and-wisdom-of-solomon',
       'Render unto Caesar — Sirach 17 and Wisdom of Solomon''s witness to the image-of-Elohim stamped on man at Matt 22:15-22',
       'Matt 22:15-22''s tribute-to-Caesar pericope — the Pharisees-and-Herodians united-against-the-King at a forced-binary-trap, the Roman-denarius bearing Tiberius Caesar''s image-and-superscription, the King''s-question *whose is this image and superscription?*, and the King''s-answer *render therefore unto Caesar the things which are Caesar''s; and unto Elohim (God) the things that are Elohim''s (God''s)* — read against the wisdom-stream''s direct articulation of the image-of-Elohim-stamped-on-man and the law-of-life-for-an-heritage substance. Four moves: Sirach (Ecclesiasticus) 17:3 names the wisdom-stream verbal-anchor for *he made them according to his image* — Sirach 17 carries the Bereshit (Genesis) 1:26-27 creation-substance forward; Sirach 17:11 names the *law of life for an heritage* substance — the Torah given to the citizen-stamped-with-the-Father''s-image as the inheritance (Sirach 24:23 names the architecture explicitly as *the book of the covenant of the most high Yahuah (God), even the law which Moses commanded for an heritage to the congregations of Ya''aqov (Jacob)*); Wisdom of Solomon 2:23 names the *image of his own eternity* substance — the citizen-stamped-with-the-image-of-Elohim''s-own-eternity; Wisdom of Solomon 9:1 names the *made all things with thy word* substance — the same Word the apostle Yochanan (John) walks at John 1:1-3 through-whom-all-things-were-made. The framework reads the cluster carefully. The Greek *eikōn* the King uses at v.20 is the same Septuagint-Greek the Genesis 1:26-27 creation-substance carries; the citizen bears the image of the Father the same way the coin bears the image of Caesar — what is stamped with the Father''s-image belongs to the Father. Per Red Line #4: Torah is NOT the curse but the law-of-life-for-an-heritage Sirach 17:11 names the wisdom-stream-substance for. Per the framework''s reading of the natural-administration: the King''s-answer is NOT the post-Constantinian collapse-of-two-co-equal-spheres; the natural-administration operates under the principalities-and-powers-of-the-darkness (Ephesians 6:12) the Father permits-for-an-age, with the categorical-precedence the apostle Kefa (Peter) walked-out at Acts 5:29 when the natural-administration-walks-against-the-Father (the Tanakh-pattern of Shadrakh (Shadrach) + Meishakh (Meshach) + Aved-Nego (Abed-nego) at Daniel 3, Daniel at Daniel 6, the prophet Eliyahu (Elijah) at 1 Kings 18, the apostle Yochanan (John)''s apocalyptic-vision at Revelation 13''s beast-and-mark substance). The wisdom-stream had named the image-architecture; the King brings the substance into-the-Pharisaic-and-Herodian-system''s-face at the tribute-coin.',
       sv.verse_id, ev.verse_id, 'complete_study', 333
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 22 AND sv.verse_number = 15
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 22 AND ev.verse_number = 22
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 334): the-resurrection-of-the-righteous-witnessed-by-the-mother-and-seven-sons-and-the-wisdom-stream
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-resurrection-of-the-righteous-witnessed-by-the-mother-and-seven-sons-and-the-wisdom-stream',
       'The resurrection of the righteous — 2 Maccabees 7''s mother-and-seven-sons witness and the wisdom-stream corroboration at Matt 22:23-33',
       'Matt 22:23-33''s Sadducees-on-resurrection question — the priestly-aristocracy-substance (the *Tsadoqim* descended from Tsadoq (Zadok) per Ezekiel 44:15-16 + 2 Samuel 8:17 + 1 Kings 1:8) whose-Torah-only-no-resurrection-no-angels-no-spirit-substance Luke names at Acts 23:8, constructing the hypothetical-substance of seven-brethren-and-one-wife on the levirate-marriage-substance of Devarim (Deuteronomy) 25:5-10 to mock the resurrection; the King''s rebuke *ye do err, not knowing the scriptures, nor the power of Elohim (God)*; *as the angels of Elohim (God) in heaven* — the non-fallen-still-in-heaven-substance (NOT the categorically-non-marrying-of-all-angels per the watcher-substance of Genesis 6:1-4 + 1 Enoch 6-7 + Jude 6); the King''s-citation of Exodus 3:6 — *I am the Elohim (God) of Avraham (Abraham), and the Elohim (God) of Yitschaq (Isaac), and the Elohim (God) of Ya''aqov (Jacob); Elohim (God) is not the Elohim (God) of the dead, but of the living* — read against the wisdom-and-martyrdom-stream''s strongest external-witness articulation of the resurrection-of-the-righteous substance. Four moves: 2 Maccabees 7:9 names THE direct verbal-anchor — the second son of the mother-and-seven-sons-substance under Antiochus Epiphanes confessing-the-*King of the world shall raise us up, who have died for his laws, to everlasting life*; 2 Maccabees 7:23 names the mother-confessing the Creator-shall-give-breath-and-life-again substance to her sons as they die for the Torah; 2 Esdras 7:32 names the earth-shall-restore-those-that-are-asleep substance the prophet Daniel had named at Daniel 12:2 carried-forward at the apocalyptic-wisdom-stream-register; Wisdom of Solomon 3:1 names the souls-of-the-righteous-in-the-hand-of-Yahuah substance — read carefully through the framework, this is the asleep-in-the-Father''s-keeping substance, NOT the inherited-Christian immediate-conscious-disembodied-soul-going-to-heaven-or-hell-at-death substance (the Wisdom of Solomon 3 surrounding-context at vv.7-8 — *and in the time of their visitation they shall shine ... they shall judge the nations* — makes plain the visitation-and-shining-and-judging belongs to the resurrection-day-substance, not to the immediate-after-death-substance). The framework reads the cluster in continuity with the apostle Yochanan (John) at Revelation 20:4-6''s *first resurrection* and the apostle Sha''ul (Paul) at 1 Thessalonians 4:13-17''s *them which are asleep ... them also which sleep in Yahusha (Jesus) will Elohim (God) bring with him* — the asleep-awaiting-the-first-resurrection substance the framework reads against the inherited-Christian collapsed-into-immediate-disembodied-substance. The substance the citizen-of-the-kingdom walks-with at the grief-of-the-loved-one is the substance the seven-martyred-sons-and-their-mother walked-with at the cost-of-blood: they-sleep-in-Yahuah-awaiting-the-King''s-coming-to-raise. The wisdom-and-martyrdom-stream had already-confessed the substance the King defends at vv.23-33 centuries before the Sadducean-trap-question.',
       sv.verse_id, ev.verse_id, 'complete_study', 334
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 22 AND sv.verse_number = 23
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 22 AND ev.verse_number = 33
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 335): love-of-yahuah-and-love-of-neighbor-as-the-shema-walked-out-in-sirach-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'love-of-yahuah-and-love-of-neighbor-as-the-shema-walked-out-in-sirach-and-wisdom-of-solomon',
       'Love of Yahuah and love of neighbor as the Shema walked out — Sirach 7, 17, 28 and Wisdom of Solomon 6''s wisdom-stream witness to Matt 22:34-40',
       'Matt 22:34-40''s great-commandment question — the Pharisaic-lawyer-substance (*nomikos* — the Torah-specialist) tempting the King with the rabbinic-ranking-game over the 613 mitzvot; the King''s Shema-citation of Devarim (Deuteronomy) 6:4-5 plus the Vayikra (Leviticus) 19:18 love-thy-neighbor substance; and the closing *on these two commandments hang all the law and the prophets* (Greek *krematai* — suspension-from-a-load-bearing-point, NOT the substance-of-replacement-of-the-Torah-by-the-two) — read against the wisdom-stream''s direct articulation of the love-Yahuah-with-all-thy-strength + commandment-concerning-the-neighbor + forgive-and-remember-the-covenant + love-is-the-keeping-of-her-laws substance. Five moves: Sirach (Ecclesiasticus) 7:30 names THE direct verbal-anchor for *love him that made you with all your strength* — the Shema-substance of Devarim (Deuteronomy) 6:5 carried-forward at the wisdom-stream-register; Sirach 17:14 names THE direct verbal-anchor for *every man commandment concerning his neighbour* — the Leviticus 19:18 substance carried-forward and named-explicitly as the Father giving-every-man-commandment-concerning-his-neighbor from-the-beginning; Sirach 28:2 names the forgive-your-neighbor substance the King will-walk at Matt 6:14-15 and the unforgiving-servant parable at Matt 18:23-35; Sirach 28:7 names the remember-the-commandments-and-the-covenant substance — binding-the-commandments-and-the-covenant together in one substance, the same architecture the King walks at Matt 22:40 (the two-commandments and the Torah-and-the-prophets are one-substance); Wisdom of Solomon 6:18 names *love is the keeping of her laws* — the same substance the apostle Yochanan (John) names explicitly at 1 John 5:2-3 (*this is the love of Elohim (God), that we keep his commandments: and his commandments are not grievous*). The framework reads the cluster in continuity with the heart-Torah-architecture of Jeremiah 31:31-34 + Ezekiel 36:26-27 + Devarim (Deuteronomy) 30:6 + Devarim 11:1 + Micah 6:8 + Hosea 6:6 — the love-of-the-Father and the keeping-of-the-commandments are one-substance walked-out from-the-inside through the new-heart-and-new-spirit. Per Red Line #4: Torah is NOT the curse; per Red Line #5: love-of-Father is NOT pitted against Torah; per Red Line #6: the Spirit is NOT separated from Torah. The wisdom-stream had walked the substance centuries before the King brings it into-the-Pharisaic-system''s-face in the Temple-court; the apostolic-restatement at Romans 13:8-10 (*love is the fulfilling of the law*) + Galatians 5:14 + James 2:8 + 1 John 4:20-21 + 1 John 5:2-3 carries the substance forward. The substance is NOT the post-Reformation collapse-of-the-Torah-into-the-two; the substance is the Torah-and-the-prophets as the detailed-walking-out of love-of-Father and love-of-neighbor in the substantive life of the citizen-of-the-kingdom.',
       sv.verse_id, ev.verse_id, 'complete_study', 335
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 22 AND sv.verse_number = 34
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 22 AND ev.verse_number = 40
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 336): the-elect-one-at-the-right-hand-the-davidic-lord-witnessed-in-1-enoch-parables
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-elect-one-at-the-right-hand-the-davidic-lord-witnessed-in-1-enoch-parables',
       'The Elect One at the right hand — 1 Enoch Parables (chs 46, 48, 51, 61, 62) and the framework-major Formless-Father / Formed-Son architecture at Matt 22:41-46 (FRAMEWORK-MAJOR)',
       'Matt 22:41-46''s David''s-Lord question — the framework-major moment for the nature-of-God substance the Synoptic-substance reaches — read against the wisdom-stream''s direct articulation of the Son-of-Adam / Elect-One named-before-the-Head-of-Days and seated-on-the-throne-of-glory at the Head-of-Days'' right hand in the Parables-of-Enoch (1 Enoch chs 37-71). Five moves: 1 Enoch 46:3 names THE direct verbal-anchor for *this is the Son of Adam who hath righteousness* — the Parables identify the Son-of-Adam by name (per Red Line #12''s Son-of-Adam architecture, this is the named-title case, NOT the kaph-comparative case of Daniel 7:13 / Revelation 1:13 / Revelation 14:14 the Red Line carves-out separately) and articulate the pre-eminence-before-Yahuah-of-Spirits substance; 1 Enoch 48:2 names the *Son of Adam was named in the presence of Yahuah (God) of Spirits, and his name before the Head of Days* — the pre-existence and eternal-naming of the Son before the foundation of the world the apostle Yochanan (John) will name at Revelation 13:8 + 17:8; 1 Enoch 51:3 names THE direct verbal-anchor for *the Elect One shall in those days sit on My throne* — the same substance Psalm 110:1 walks at *sit thou on my right hand*; 1 Enoch 61:8 names the Head-of-Days placing-the-Elect-One on-the-throne-of-His-glory substance; 1 Enoch 62:7 names the Son-of-Adam-born-unto-righteousness substance — the Davidic-lineage AND the righteousness-of-the-Head-of-Days abiding-over-him from-the-foundation-of-the-world. The framework reads the cluster as FRAMEWORK-MAJOR for the nature-of-God reading. The Tanakh-Hebrew of Psalm 110:1 preserves the substance with precision: the first *Lord* is *Yahuah* (the tetragrammaton, the Formless-Father per the framework''s Formless-Source / Formed-Expression-from-the-Source nature-of-God reading); the second *Lord* is *Adoni* (David''s personal-Lord, the Son the Davidic-lineage produces AND who is greater than David). The substance the King brings-into-the-Pharisaic-system''s-face at Matt 22:41-46 is the substance 1 Enoch had named at the wisdom-stream-register: the Son-of-Adam is greater-than-David because the Son-of-Adam was-named before-the-Head-of-Days before-the-Davidic-line-existed, and the Father (the Head of Days / Yahuah of Spirits) gives-the-throne-and-the-judgment-of-the-works-of-the-holy to-the-Elect-One. The substance rules out three inherited readings of the nature-of-God: (i) the post-Nicene Trinitarian three-co-equal-persons-of-one-substance — both Psalm 110 and 1 Enoch 51:3 / 61:8 carry the Father-placing-the-Son-on-the-throne substance, substantive-subordination at the eternal-Source-and-Expression level (the King-himself walks the same substance at John 14:28 / 1 Corinthians 15:28 / Matthew 24:36); (ii) the modalist-collapse — the Father speaks TO the Son the same way the Head of Days names the Son, the two are substantively-distinct; (iii) the Arian-substance of the Son as a created-being made-at-a-point-in-time — the Son was-named before-the-Head-of-Days, the Word the apostle Yochanan (John) names at John 1:1-3 (*in the beginning was the Word, and the Word was with Elohim (God), and the Word was Elohim (God) ... all things were made by him*). Psalm 110 is the most-quoted Tanakh-Psalm in the apostolic-substance: the King-himself at Matt 26:64; Kefa-Pentecost at Acts 2:34-36; Stephen at Acts 7:55-56; the apostle Sha''ul (Paul) at Romans 8:34, 1 Corinthians 15:25, Ephesians 1:20, Colossians 3:1; Hebrews 1:3, 1:13, 5:6, 7:17, 7:21, 8:1, 10:12-13, 12:2; the apostle Kefa (Peter) at 1 Peter 3:22; the apostle Yochanan (John) at Revelation 3:21. The system-substance has no answer at the King''s-substance; *and no man was able to answer him a word, neither durst any man from that day forth ask him any more questions* — the public-questioning is closed, the road to the cross opens, the husbandmen-parable-substance of Matt 21:38 walks-out within the week. The wisdom-stream and the Tanakh and the gospel and the apostolic-substance all cohere at the substance the framework''s Formless-Father / Formed-Son architecture reads.',
       sv.verse_id, ev.verse_id, 'complete_study', 336
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 22 AND sv.verse_number = 41
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 22 AND ev.verse_number = 46
ON CONFLICT (slug) DO NOTHING;

