-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s155_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 22
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-wedding-feast-and-the-garments-of-the-righteous-in-2-esdras-and-wisdom-of-solomon',
     'render-unto-caesar-and-the-image-of-elohim-stamped-on-man-in-sirach-and-wisdom-of-solomon',
     'the-resurrection-of-the-righteous-witnessed-by-the-mother-and-seven-sons-and-the-wisdom-stream',
     'love-of-yahuah-and-love-of-neighbor-as-the-shema-walked-out-in-sirach-and-wisdom-of-solomon',
     'the-elect-one-at-the-right-hand-the-davidic-lord-witnessed-in-1-enoch-parables'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-wedding-feast-and-the-garments-of-the-righteous-in-2-esdras-and-wisdom-of-solomon',
     'render-unto-caesar-and-the-image-of-elohim-stamped-on-man-in-sirach-and-wisdom-of-solomon',
     'the-resurrection-of-the-righteous-witnessed-by-the-mother-and-seven-sons-and-the-wisdom-stream',
     'love-of-yahuah-and-love-of-neighbor-as-the-shema-walked-out-in-sirach-and-wisdom-of-solomon',
     'the-elect-one-at-the-right-hand-the-davidic-lord-witnessed-in-1-enoch-parables'
   );

  RAISE NOTICE 'S155 Matt 22 verify: extras xrefs from canon/matthew/22 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 Matt-22 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
